namespace sarif.export;



using com.google.gson;
using com.google.gson;

using ghidra.program.model.data.ISF;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

public class SarifWriterTask : Task {

	protected AbstractIsfWriter writer;
	protected JsonArray results;

	public SarifWriterTask(string tag, AbstractIsfWriter writer, JsonArray results) : base(tag, true, false, true)
    {
		this.writer = writer;
		this.results = results;
	}

	/* @Override */
	public void run(TaskMonitor monitor) {
		try {
			try {
				writer.getRootObject(monitor);
				JsonArray res = writer.getResults();
				foreach (JsonElement element in res) {
					if (monitor.isCancelled()) {
						break;
					}
					results.add(element);
				}
			} finally {
				writer.close();
			}
		} catch (CancelledException e) {
			// user cancelled; ignore
		} catch (IOException e) {
			Msg.error("Export Data Types Failed", "Error exporting Data Types: " + e);
			return;
		}
	}
}
